1	package org.springframework.samples.petclinic.acceptance;
2	
3	import org.junit.jupiter.api.Tag;
4	import org.junit.jupiter.api.Test;
5	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
6	import tools.jackson.databind.node.ObjectNode;
7	
8	/** address-normalize: normalization (upper-case, collapse whitespace, expand
9	 * ST->STREET) now applies to the structured address lines. */
10	@Tag("cp12")
11	class Cp12Tests extends AcceptanceBase {
12	
13		@Test
14		void coreNormalizesAddressLine() throws Exception {
15			ObjectNode o = structuredOwner();
16			o.put("addressLine1", "  10  king  st ");
